{
  "story": "Follow one idealized gasoline cylinder, starting just after intake. Its flywheel already spins; valve overlap and early ignition are omitted. Advance through compression, power, and exhaust. Compare valve positions and energy direction. At exhaust completion, count the crankshaft turns required for a single power stroke.",
  "aha": {
    "stateId": "exhaust-complete",
    "observation": "Each cylinder produces one power stroke per two crankshaft revolutions, because completing the cycle requires four piston strokes."
  },
  "layout": {
    "preset": "approved-card/stepper-states/cycle",
    "width": 640
  },
  "parts": [
    {
      "id": "cycle-rail",
      "kind": "step-rail",
      "presentation": "Place below the story and instructions. Show ordered stroke summaries, the active state, and prior-state trace within the rail. Detailed parameter-control budget: zero. Navigation budget: one index control plus Reset.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "cycle-picture",
      "kind": "fixed-picture",
      "presentation": "Use the canonical cycle arrangement with four fixed phase regions and a shared crankshaft region. Region values supply all mechanism labels. Highlight active regions and their connecting links. Each phase summarizes a completed stroke before the next stroke changes valve positions. Piston endpoints share top and bottom references; travel arrows are qualitative, not animated or dimensioned. Keep all phases visible for comparison, with readable labels at native width.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "stroke-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the active phase without covering its labels. Identify the mechanism and its cause; keep numerical evidence in the readouts.",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "cycle-evidence",
      "kind": "value-readout",
      "presentation": "Place below the picture, with the bound status last. Counts begin at top dead center immediately before intake. Each full piston stroke advances the crankshaft by half a revolution. Derive crankshaft revolutions as completed strokes divided by two. Count power strokes only after expansion finishes. Counts and revolutions are exact, without rounding.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stroke",
      "kind": "index",
      "presentation": "Default to the first state; bounds are the first and last states; increment is one state. Use Previous and Next, retaining their names when disabled at boundaries. Every state persists until learner action, including the aha state. Reference captures show the aha state. Support keyboard activation, arrow-key stepping, accessible names, and visible focus.",
      "items": "variant.states",
      "label": "Engine stroke"
    },
    {
      "id": "reset",
      "kind": "reset",
      "presentation": "Restore the first state and all defaults. Support Enter and Space, an accessible name, and visible focus.",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Idealized four-stroke gasoline cylinder",
        "regions": [
          {
            "id": "intake",
            "label": "Intake",
            "values": [
              "Piston: top → bottom",
              "Intake valve: open",
              "Exhaust valve: closed",
              "Fuel–air mixture: enters cylinder",
              "Spark plug: inactive"
            ]
          },
          {
            "id": "compression",
            "label": "Compression",
            "values": [
              "Piston: bottom → top",
              "Intake valve: closed",
              "Exhaust valve: closed",
              "Fuel–air mixture: squeezed into less space",
              "Spark plug: not fired yet"
            ]
          },
          {
            "id": "power",
            "label": "Power",
            "values": [
              "Piston: top → bottom",
              "Intake valve: closed",
              "Exhaust valve: closed",
              "Burning mixture: expands against piston",
              "Spark plug: fires at stroke start"
            ]
          },
          {
            "id": "exhaust",
            "label": "Exhaust",
            "values": [
              "Piston: bottom → top",
              "Intake valve: closed",
              "Exhaust valve: open",
              "Burned gas: pushed out",
              "Spark plug: inactive"
            ]
          },
          {
            "id": "crankshaft",
            "label": "Crankshaft, connecting rod, and flywheel",
            "values": [
              "Connecting rod links piston travel to crankshaft rotation.",
              "Flywheel begins with stored rotational energy.",
              "Power replenishes energy used during the other strokes."
            ]
          }
        ],
        "links": [
          {
            "from": "crankshaft",
            "to": "intake",
            "label": "Stored rotation drives piston"
          },
          {
            "from": "crankshaft",
            "to": "compression",
            "label": "Stored rotation compresses mixture"
          },
          {
            "from": "power",
            "to": "crankshaft",
            "label": "Expanding gas drives crankshaft"
          },
          {
            "from": "crankshaft",
            "to": "exhaust",
            "label": "Stored rotation clears cylinder"
          }
        ],
        "states": [
          {
            "id": "intake-complete",
            "label": "After intake",
            "short": "Intake",
            "sentence": "The descending piston draws fresh fuel–air mixture through the open intake valve.",
            "why": "The crankshaft and connecting rod move the piston; the resulting pressure difference admits the mixture.",
            "active": [
              "intake",
              "crankshaft"
            ],
            "calloutRegion": "intake",
            "readouts": [
              {
                "id": "completed-strokes",
                "label": "Completed piston strokes",
                "value": "1"
              },
              {
                "id": "crank-revolutions",
                "label": "Crankshaft rotation · strokes ÷ 2",
                "value": "0.5 rev"
              },
              {
                "id": "completed-power-strokes",
                "label": "Completed power strokes",
                "value": "0"
              },
              {
                "id": "energy-direction",
                "label": "Mechanical energy direction",
                "value": "Crankshaft → piston"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Fresh mixture admitted; compression comes next."
              }
            ]
          },
          {
            "id": "compression-complete",
            "label": "After compression",
            "short": "Compression",
            "sentence": "The rising piston compresses the trapped mixture while both valves remain closed.",
            "why": "Closing both valves prevents escape, so piston motion reduces the mixture’s volume before ignition.",
            "active": [
              "compression",
              "crankshaft"
            ],
            "calloutRegion": "compression",
            "readouts": [
              {
                "id": "completed-strokes",
                "label": "Completed piston strokes",
                "value": "2"
              },
              {
                "id": "crank-revolutions",
                "label": "Crankshaft rotation · strokes ÷ 2",
                "value": "1 rev"
              },
              {
                "id": "completed-power-strokes",
                "label": "Completed power strokes",
                "value": "0"
              },
              {
                "id": "energy-direction",
                "label": "Mechanical energy direction",
                "value": "Crankshaft → piston → mixture"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Mixture compressed; spark and expansion come next."
              }
            ]
          },
          {
            "id": "power-complete",
            "label": "After power",
            "short": "Power",
            "sentence": "The spark starts combustion; expanding gas pushes the piston down and turns the crankshaft.",
            "why": "Both valves remain closed, as during compression, but expanding gas now supplies mechanical energy instead of receiving it.",
            "active": [
              "power",
              "crankshaft"
            ],
            "calloutRegion": "power",
            "readouts": [
              {
                "id": "completed-strokes",
                "label": "Completed piston strokes",
                "value": "3"
              },
              {
                "id": "crank-revolutions",
                "label": "Crankshaft rotation · strokes ÷ 2",
                "value": "1.5 rev"
              },
              {
                "id": "completed-power-strokes",
                "label": "Completed power strokes",
                "value": "1"
              },
              {
                "id": "energy-direction",
                "label": "Mechanical energy direction",
                "value": "Expanding gas → piston → crankshaft"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Combustion has delivered work; burned gas still needs removal."
              }
            ]
          },
          {
            "id": "exhaust-complete",
            "label": "After exhaust",
            "short": "Exhaust",
            "sentence": "The rising piston pushes burned gas through the open exhaust valve, completing the cycle.",
            "why": "Intake, compression, and exhaust require continued rotation; only the power stroke adds combustion-driven work to the crankshaft.",
            "active": [
              "exhaust",
              "crankshaft"
            ],
            "calloutRegion": "exhaust",
            "readouts": [
              {
                "id": "completed-strokes",
                "label": "Completed piston strokes",
                "value": "4"
              },
              {
                "id": "crank-revolutions",
                "label": "Crankshaft rotation · strokes ÷ 2",
                "value": "2 rev"
              },
              {
                "id": "completed-power-strokes",
                "label": "Completed power strokes",
                "value": "1"
              },
              {
                "id": "energy-direction",
                "label": "Mechanical energy direction",
                "value": "Crankshaft → piston"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Cycle complete; compare total crankshaft rotation with the power-stroke count."
              }
            ]
          }
        ]
      }
    ]
  }
}
